import{_ as i}from"./chunks/Audio.COine8Wh.js";import{_ as o}from"./chunks/Tags.BJ536pW3.js";import{c as s,o as a,j as t,G as r,ae as n,a as c}from"./chunks/framework.Bw0Gm4PQ.js";const h=JSON.parse('{"title":"Homebuyers Privacy Protection Act","description":"","frontmatter":{"legisId":"2025-09-05-homebuyers-privacy-protection-act","title":"Homebuyers Privacy Protection Act","displayTitle":"Homebuyers Privacy Protection Act","lawNumber":"119-36","billNumber":"H.R. 2808","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ36.xml","publishDate":"2025-09-05T00:00:00-05:00","industries":["finance","housing"],"agencies":["Government Accountability Office"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Homebuyers Privacy Protection Act\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-09-05-homebuyers-privacy-protection-act\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Homebuyers Privacy Protection Act\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-09-05-homebuyers-privacy-protection-act\\",\\"datePublished\\":\\"2025-09-05T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-09-05-homebuyers-privacy-protection-act\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-09-05-homebuyers-privacy-protection-act.md","filePath":"congress-bills/2025-09-05-homebuyers-privacy-protection-act.md","lastUpdated":1788887623000}'),l={name:"congress-bills/2025-09-05-homebuyers-privacy-protection-act.md"},f=Object.assign(l,{setup(u){return(m,e)=>(a(),s("div",null,[e[0]||(e[0]=t("h1",{id:"homebuyers-privacy-protection-act",tabindex:"-1"},[c("Homebuyers Privacy Protection Act "),t("a",{class:"header-anchor",href:"#homebuyers-privacy-protection-act","aria-label":'Permalink to "Homebuyers Privacy Protection Act"'},"​")],-1)),r(i),r(o,{list:"/congress-bills"}),e[1]||(e[1]=n('<p>Signed into law on Friday, September 5, 2025. Public Law 119-36, H.R. 2808.</p><p><strong>Headline:</strong> The law restricts mortgage-related credit report sales leads to protect homebuyers’ privacy.</p><p><strong>Why it matters:</strong> Consumers seeking mortgages will face fewer unsolicited offers based on their credit report requests. Sharing is generally limited to businesses with the consumer’s permission or an existing financial relationship.</p><p><strong>What the law does:</strong></p><ul><li>Bars credit reporting agencies from using mortgage credit report requests to share consumer reports unless specified conditions are met.</li><li>Requires resulting offers to be firm offers of credit or insurance.</li><li>Limits eligible recipients to consumer-authorized persons, current mortgage originators or servicers, and banks or credit unions where the consumer has an account.</li><li>Directs the Government Accountability Office to study mortgage sales leads sent by text and report to Congress within 12 months of enactment.</li><li>Takes effect 180 days after its September 5, 2025 enactment.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Consumers applying for or seeking mortgages.</li><li>Credit reporting agencies and businesses that buy mortgage-related leads.</li><li>Mortgage originators, servicers, banks, and credit unions.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>A mortgage credit check generally cannot trigger offers from unrelated businesses without authorization or an existing financial relationship.</li><li>Any permitted outreach based on the credit request must involve a firm offer of credit or insurance.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="homebuyers-privacy-protection-act-1" tabindex="-1">Homebuyers Privacy Protection Act <a class="header-anchor" href="#homebuyers-privacy-protection-act-1" aria-label="Permalink to &quot;Homebuyers Privacy Protection Act&quot;">​</a></h3><p>The Homebuyers Privacy Protection Act limits when credit reporting agencies may share a consumer’s information after a mortgage-related credit report request generates a sales lead. It generally allows sharing only for firm offers of credit or insurance involving a person authorized by the consumer, the consumer’s current mortgage lender or servicer, or a bank or credit union where the consumer has an account. It also requires a federal study of mortgage-related leads sent by text message.</p><p><strong>Key takeaways:</strong></p><ul><li>Credit reporting agencies generally may not use a mortgage credit report request to provide the consumer’s report to other businesses unless specified conditions are met.</li><li>Any resulting offer must be a firm offer of credit or insurance.</li><li>Eligible recipients are limited to persons authorized by the consumer, the originator or servicer of the consumer’s current mortgage, or a bank or credit union where the consumer has a current account.</li><li>The Government Accountability Office must study the value of mortgage-related sales leads received by text message and report its findings to Congress within 12 months after enactment.</li><li>The law takes effect 180 days after its September 5, 2025 enactment.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ36.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ36.xml</a></p>',15))]))}});export{h as __pageData,f as default};
